Given an integer k and a queueq of integers, reverse the order of the first k elements of the queue, leaving the other elements in the same relative order.Only following standard operations are allowed on the queue. enqueue(x): Add an item x to rear of queuedequeue(): Remove an item from the front of the queuesize(): Returns the number of elements in the queue.front(): Finds front item.Note: If the size of queue is smaller than the given k , then return the original queue.Example: Input: q = [1, 2, 3, 4, 5], k = 3Output: [3, 2, 1, 4, 5]Explanation:  After reversing the first 3 elements from the given queue the resultant queue will be [3, 2, 1, 4, 5].Input: q = [4, 3, 2, 1], k= 4Output: [1, 2, 3, 4]Explanation: After reversing the first 4 elements from the given queue the resultant queue will be [1, 2, 3, 4].Try It YourselfTable of ContentUsing the Recursion Call Stack - O(n) Time O(n) SpaceUsing a Stack - O(n + k) Time O(k) SpaceUsing the Recursion Call Stack - O(n) Time O(n) SpaceThe idea is to remove and store the first k elements in recursive call stack and insert them in the queue in the reverse order then we can simply remove and add remaining items of the queue. Algorithm:Recursively remove the first k elements, then add them back during backtracking -> this reverses their order.  Rotate the remaining (n − k) elements from front to back -> to maintain their original order.
            C++

    #include <iostream>
#include<vector>
using namespace std;

void moveKToEnd(queue<int>& q, int k) {
    if (k == 0) return;
    int e = q.front();
    q.pop();
    moveKToEnd(q, k - 1);
    q.push(e);
}

// Main function to reverse first k elements of a queue
queue<int> reverseFirstK(queue<int> q, int k) {

    if(k > q.size())return q;

    moveKToEnd(q, k);
    int s = q.size() - k;
    while (s-- > 0) {
        int x = q.front();
        q.pop();
        q.push(x);
    }
    return q;
}

int main() {
    queue<int> queue;
    queue.push(1);
    queue.push(2);
    queue.push(3);
    queue.push(4);
    queue.push(5);

    int k = 3;
    queue = reverseFirstK(queue, k);

    // Printing queue
    while (!queue.empty()) {
        cout << queue.front() << " ";
        queue.pop();
    }
    return 0;
}


