    using System;
using System.Collections.Generic;

class GFG {

    static Queue<int> reverseFirstK(Queue<int> q, int k) {

        if (k > q.Count) return q;

        moveKToEnd(q, k);

        int s = q.Count - k;
        while (s > 0) {
            int x = q.Dequeue();
            q.Enqueue(x);
            s = s - 1;
        }

        return q;
    }

    static void moveKToEnd(Queue<int> q, int k) {
        if (k == 0) {
            return;
        }

        int e = q.Dequeue();
        moveKToEnd(q, k - 1);
        q.Enqueue(e);
    }

    public static void Main(string[] args) {

        Queue<int> q = new Queue<int>();
        q.Enqueue(1);
        q.Enqueue(2);
        q.Enqueue(3);
        q.Enqueue(4);
        q.Enqueue(5);

        int k = 3;

        q = reverseFirstK(q, k);

        while (q.Count > 0) {
            Console.Write(q.Dequeue() + " ");
        }
    }
}


