            C#

    using System;
using System.Collections.Generic;

class GFG {

    // Function to reverse the first
    //   K elements of the Queue 
    static Queue<int> reverseFirstK(Queue<int> q, int k) {
        if (q.Count == 0 || k > q.Count)
            return q;
        if (k <= 0)
            return q;

        Stack<int> s = new Stack<int>();

        // Push the first K elements
        //   into a Stack
        for (int i = 0; i < k; i++) {
            s.Push(q.Dequeue());
        }

        // Enqueue the contents of stack
        //   at the back of the queue
        while (s.Count > 0) {
            q.Enqueue(s.Pop());
        }

        // Remove the remaining elements and
        //   enqueue them at the end of the Queue
        for (int i = 0; i < q.Count - k; i++) {
            q.Enqueue(q.Dequeue());
        }

        return q;
    }

    // Utility Function to print the Queue 
    static void Print(Queue<int> q) {
        while (q.Count > 0) {
            Console.Write(q.Dequeue() + " ");
        }
    }

    static void Main() {
        Queue<int> q = new Queue<int>();
        q.Enqueue(1);
        q.Enqueue(2);
        q.Enqueue(3);
        q.Enqueue(4);
        q.Enqueue(5);

        int k = 3;
        Queue<int> res = reverseFirstK(q, k);
        Print(q);
    }
}


